122	/// Where `offset` in `before` lands in `after`, the same text reformatted,
123	/// which changes only whitespace: against the same character it was
124	/// against, or else just after the same one, then as many line breaks on
125	/// and as many spaces along as the formatted text allows.
126	fn offset_after_formatting(before: &str, after: &str, offset: usize) -> usize {
127	    let offset = offset.min(before.len());
128	    let head = &before[..offset];
129	    let solid = head.chars().filter(|c| !c.is_whitespace()).count();
130	    // What lay between the last character and the cursor.
131	    let gap = &head[head.trim_end().len()..];
132	    let breaks = gap.matches('\n').count();
133	    let column = gap
134	        .rsplit('\n')
135	        .next()
136	        .map_or(0, |tail| tail.chars().count());
137	
138	    let mut at = 0;
139	    let mut seen = 0;
140	    for (ix, c) in after.char_indices() {
141	        if seen == solid {
142	            break;
143	        }
144	        if !c.is_whitespace() {
145	            seen += 1;
146	        }
147	        at = ix + c.len_utf8();
148	    }
149	    if seen < solid {
150	        return after.len();
151	    }
152	    // Against a character, it stays against it.
153	    if before[offset..].starts_with(|c: char| !c.is_whitespace()) {
154	        return after[at..]
155	            .find(|c: char| !c.is_whitespace())
156	            .map_or(after.len(), |next| at + next);
157	    }
158	    // Then as many line breaks on, where the formatted text still has them.
159	    for _ in 0..breaks {
160	        match after[at..].find('\n') {
161	            Some(newline) if after[at..at + newline].trim().is_empty() => at += newline + 1,
162	            _ => break,
163	        }
164	    }
165	    // And as far along the line as it was, without passing its next character.
166	    let room = after[at..]
167	        .char_indices()
168	        .take_while(|(_, c)| *c == ' ' || *c == '\t')
169	        .take(column)
170	        .last()
171	        .map_or(0, |(ix, c)| ix + c.len_utf8());
172	    at + room
173	}
