175	impl FileView {
176	    /// Opens the file at `path`, with the cursor at `position` if given.
177	    pub fn new(
178	        path: PathBuf,
179	        position: Option<Position>,
180	        window: &mut Window,
181	        cx: &mut Context<Self>,
182	    ) -> Self {
183	        let title = match ProjectDirectory::get(cx) {
184	            Some(root) => path
185	                .strip_prefix(&root)
186	                .unwrap_or(&path)
187	                .display()
188	                .to_string(),
189	            None => path.display().to_string(),
190	        };
191	        let language = language_for(&path);
192	        let editor = cx.new(|cx| {
193	            EditorState::new(window, cx)
194	                .language(language.clone())
195	                .tab_size(TabSize {
196	                    tab_size: TAB_SIZE,
197	                    hard_tabs: false,
198	                })
199	                .soft_wrap(false)
200	                .placeholder("Loading…")
201	        });
202	
203	        let subscriptions = vec![
204	            cx.subscribe_in(
205	                &editor,
206	                window,
207	                |this, _, event: &InputEvent, window, cx| {
208	                    if matches!(event, InputEvent::Change) {
209	                        // What was selected has changed under the popover.
210	                        this.selection_popover = None;
211	                        this.on_edit(window, cx);
212	                    }
213	                },
214	            ),
215	            cx.observe_global_in::<ProjectLsp>(window, |this, _, cx| this.attach_lsp(cx)),
216	        ];
217	
218	        let read = cx.background_spawn({
219	            let path = path.clone();
220	            async move { std::fs::read_to_string(path) }
221	        });
222	        let load = cx.spawn_in(window, async move |this, cx| {
223	            let text = read.await;
224	            this.update_in(cx, |this, window, cx| {
225	                match text {
226	                    Ok(text) => {
227	                        this.editor.update(cx, |editor, cx| {
228	                            editor.set_value(text, window, cx);
229	                            if let Some(position) = position {
230	                                editor.set_cursor_position(position, window, cx);
231	                            }
232	                        });
233	                        // As the editor holds it, line endings normalized.
234	                        this.saved = Some(this.editor.read(cx).value().to_string());
235	                        this.attach_lsp(cx);
236	                    }
237	                    Err(err) => {
238	                        this.error = Some(format!("Could not show this file: {err}").into())
239	                    }
240	                }
241	                cx.notify();
242	            })
243	            .ok();
244	        });
245	
246	        Self {
247	            path,
248	            language,
249	            title: title.into(),
250	            editor,
251	            error: None,
252	            save_error: None,
253	            saved: None,
254	            dirty: false,
255	            document: None,
256	            diagnostics: Vec::new(),
257	            selection_popover: None,
258	            _load: load,
259	            _save: Task::ready(()),
260	            _watch_diagnostics: Task::ready(()),
261	            _subscriptions: subscriptions,
262	        }
263	    }
