265	    /// Shows a file that isn't on disk yet, starting with `text`, the cursor
266	    /// at `cursor`: unsaved from the start, and written, folders and all,
267	    /// when saved.
268	    pub fn unwritten(
269	        path: PathBuf,
270	        text: String,
271	        cursor: Position,
272	        window: &mut Window,
273	        cx: &mut Context<Self>,
274	    ) -> Self {
275	        let mut this = Self::new(path, None, window, cx);
276	        // There is nothing to read: dropping the load stops it.
277	        this._load = Task::ready(());
278	        this.editor.update(cx, |editor, cx| {
279	            editor.set_value(text, window, cx);
280	            editor.set_cursor_position(cursor, window, cx);
281	        });
282	        // Nothing is saved yet, so everything in it is a change.
283	        this.saved = Some(String::new());
284	        this.dirty = true;
285	        this.attach_lsp(cx);
286	        this
287	    }
