303	    /// Asks whether to discard the unsaved changes to the file titled
304	    /// `title`, and runs `discard` if so.
305	    pub fn confirm_discard(
306	        title: SharedString,
307	        window: &mut Window,
308	        cx: &mut App,
309	        discard: impl Fn(&mut Window, &mut App) + 'static,
310	    ) {
311	        let discard = Rc::new(discard);
312	        window.open_alert_dialog(cx, move |alert, _, _| {
313	            let discard = discard.clone();
314	            alert
315	                .title("Discard unsaved changes?")
316	                .description(SharedString::from(format!(
317	                    "{title} has changes that have not been saved."
318	                )))
319	                .button_props(
320	                    DialogButtonProps::default()
321	                        .ok_text("Discard")
322	                        .ok_variant(ButtonVariant::Danger)
323	                        .show_cancel(true),
324	                )
325	                .on_ok(move |_, window, cx| {
326	                    discard(window, cx);
327	                    true
328	                })
329	        });
330	    }
