332	    /// Moves keyboard focus into the editor.
333	    pub fn focus_editor(&mut self, window: &mut Window, cx: &mut Context<Self>) {
334	        use gpui_kit::Focusable as _;
335	        self.editor.read(cx).focus_handle(cx).focus(window, cx);
