338	    fn on_edit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
339	        let Some(saved) = &self.saved else {
340	            return;
341	        };
342	        let text = self.editor.read(cx).value();
343	        self.dirty = text.as_ref() != saved;
344	        // What the pointer's hover showed goes as soon as the text changes.
345	        self.editor.update(cx, |editor, cx| {
346	            editor.clear_hover_state(cx);
347	            editor.clear_diagnostic_popover(cx);
348	        });
349	
350	        if let Some(document) = &self.document {
351	            document.sync(&text);
352	            let imports = document.take_accepted_imports(&text);
353	            if !imports.is_empty() {
354	                self.editor.update(cx, |editor, cx| {
355	                    editor.apply_lsp_edits(&imports, window, cx)
356	                });
357	            }
358	        }
359	        // The editor drops its diagnostics on every edit.
360	        self.show_diagnostics(cx);
361	        cx.notify();
362	    }
363	
364	    /// Writes the file to disk. A Piton file is first formatted with
365	    /// `piton format`, and the editor shows the formatted text; one that
366	    /// cannot be formatted is saved as it is.
367	    fn save(&mut self, window: &mut Window, cx: &mut Context<Self>) {
368	        if self.saved.is_none() {
369	            return;
370	        }
371	        let typed = self.editor.read(cx).value().to_string();
372	        let is_piton = self.path.extension().is_some_and(|ext| ext == "pi");
373	        let project_dir = ProjectDirectory::get(cx);
374	        let write = cx.background_spawn({
375	            let path = self.path.clone();
376	            let typed = typed.clone();
377	            async move {
378	                let text = if is_piton {
379	                    let dir = project_dir
380	                        .or_else(|| path.parent().map(Path::to_path_buf))
381	                        .unwrap_or_default();
382	                    format_piton(&typed, &dir).unwrap_or(typed)
383	                } else {
384	                    typed
385	                };
386	                // A file not yet on disk may need its folders made.
387	                if let Some(parent) = path.parent() {
388	                    std::fs::create_dir_all(parent)?;
389	                }
390	                // Saved here, it is kept even where a running task may not
391	                // change it.
392	                crate::mode_guard::saving(&path, text.as_bytes());
393	                std::fs::write(path, &text).map(|()| text)
394	            }
395	        });
396	        self._save = cx.spawn_in(window, async move |this, cx| {
397	            let written = write.await;
398	            this.update_in(cx, |this, window, cx| {
399	                match written {
400	                    Ok(text) => {
401	                        this.save_error = None;
402	                        // Shows the formatted text, unless the file was edited
403	                        // again while it saved.
404	                        if text != typed && this.editor.read(cx).value().as_ref() == typed {
405	                            // The cursor and the view stay where they were.
406	                            this.editor.update(cx, |editor, cx| {
407	                                let selected = editor.selected_range();
408	                                let scroll = editor.scroll_offset();
409	                                editor.set_value(text.clone(), window, cx);
410	                                let start = offset_after_formatting(&typed, &text, selected.start);
411	                                let end = offset_after_formatting(&typed, &text, selected.end);
412	                                editor.set_selected_range(start..end, cx);
413	                                editor.set_scroll_offset(scroll, cx);
414	                            });
415	                            if let Some(document) = &this.document {
416	                                document.sync(&text);
417	                            }
418	                        }
419	                        this.dirty = this.editor.read(cx).value().as_ref() != text;
420	                        this.saved = Some(text);
421	                        if let Some(document) = &this.document {
422	                            document.did_save();
423	                        }
424	                    }
425	                    Err(err) => {
426	                        this.save_error = Some(format!("Could not save this file: {err}").into())
427	                    }
428	                }
429	                cx.notify();
430	            })
431	            .ok();
432	        });
433	    }
