453	    /// Does what `action` does in the editor, Cut, Copy, or Paste, with the
454	    /// editor focused, closing the popover.
455	    fn edit_selection(
456	        &mut self,
457	        action: Box<dyn Action>,
458	        window: &mut Window,
459	        cx: &mut Context<Self>,
460	    ) {
461	        self.selection_popover = None;
462	        let focus = self.editor.read(cx).focus_handle(cx);
463	        focus.focus(window, cx);
464	        // Straight to the editor, as its own shortcut would be.
465	        focus.dispatch_action(action.as_ref(), window, cx);
466	        cx.notify();
467	    }
468	
469	    /// Attaches the selected text to the prompt, closing the popover.
470	    fn send_selection_to_prompt(&mut self, window: &mut Window, cx: &mut Context<Self>) {
471	        self.selection_popover = None;
472	        let text = self.editor.read(cx).selected_text().to_string();
473	        if !text.is_empty() {
474	            cx.emit(SendToPrompt(text));
475	        }
476	        self.editor.read(cx).focus_handle(cx).focus(window, cx);
477	        cx.notify();
478	    }
479	
480	    /// The popover by text selected in the editor: Cut, Copy, Paste, and Send
481	    /// to Prompt. Pressing the mouse anywhere else closes it.
482	    fn render_selection_popover(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
483	        let position = self.selection_popover?;
484	        // Cut and Paste change the file, which can't be edited until it's in.
485	        let editable = self.saved.is_some();
486	        let this = cx.entity().downgrade();
487	        let edit = |action: fn() -> Box<dyn Action>| {
488	            let this = this.clone();
489	            move |_: &ClickEvent, window: &mut Window, cx: &mut App| {
490	                this.update(cx, |this, cx| this.edit_selection(action(), window, cx))
491	                    .ok();
492	            }
493	        };
494	        let actions = vec![
495	            SelectionAction::new("cut", IconName::Scissors, "Cut", edit(|| Box::new(Cut)))
496	                .disabled(!editable),
497	            SelectionAction::new("copy", IconName::Copy, "Copy", edit(|| Box::new(Copy))),
498	            SelectionAction::new(
499	                "paste",
500	                IconName::ClipboardPaste,
501	                "Paste",
502	                edit(|| Box::new(Paste)),
503	            )
504	            .disabled(!editable),
505	            SelectionAction::new("send", IconName::Paperclip, "Send to Prompt", {
506	                let this = this.clone();
507	                move |_, window, cx| {
508	                    this.update(cx, |this, cx| this.send_selection_to_prompt(window, cx))
509	                        .ok();
510	                }
511	            }),
512	        ];
513	        Some(selection_popover(
514	            "editor-selection",
515	            position,
516	            actions,
517	            move |_, cx| {
518	                this.update(cx, |this, cx| {
519	                    this.selection_popover = None;
520	                    cx.notify();
521	                })
522	                .ok();
523	            },
524	            cx,
525	        ))
526	    }
