536	    /// Closes the file, first asking whether to discard any unsaved changes.
537	    pub fn close(&mut self, window: &mut Window, cx: &mut Context<Self>) {
538	        if !self.dirty {
539	            cx.emit(CloseFile);
540	            return;
541	        }
542	        let this = cx.entity().downgrade();
543	        Self::confirm_discard(self.title.clone(), window, cx, move |_, cx| {
544	            this.update(cx, |_, cx| cx.emit(CloseFile)).ok();
545	        });
546	    }
