548	    /// Opens the file in the project's `piton lsp` and points the editor's
549	    /// language support at it, or takes that away when the file is not Piton
550	    /// or the server is not running.
551	    fn attach_lsp(&mut self, cx: &mut Context<Self>) {
552	        let is_piton = self.path.extension().is_some_and(|ext| ext == "pi");
553	        // A file kept for a project not on screen isn't in the server, which
554	        // is the project on screen's, until its project is back.
555	        let on_screen = ProjectDirectory::get(cx).is_some_and(|dir| self.path.starts_with(dir));
556	        let client = ProjectLsp::get(cx).filter(|_| is_piton && on_screen && self.saved.is_some());
557	        let attached = self
558	            .document
559	            .as_ref()
560	            .map(|document| Arc::as_ptr(&document.client));
561	        if client.as_ref().map(Arc::as_ptr) == attached {
562	            return;
563	        }
564	
565	        let text = self.editor.read(cx).value();
566	        self.document = client.map(|client| Arc::new(Document::open(client, &self.path, &text)));
567	        self.diagnostics = Vec::new();
568	        self._watch_diagnostics = Task::ready(());
569	
570	        let file = self
571	            .document
572	            .clone()
573	            .map(|document| Rc::new(PitonFile { document }));
574	        let this = cx.entity().downgrade();
575	        self.editor.update(cx, |editor, _| {
576	            let lsp = editor.lsp_mut();
577	            lsp.completion_provider = file.clone().map(|file| file as Rc<dyn CompletionProvider>);
578	            lsp.hover_provider = file.clone().map(|file| file as Rc<dyn HoverProvider>);
579	            lsp.definition_provider = file.clone().map(|file| file as Rc<dyn DefinitionProvider>);
580	            lsp.code_action_providers = file
581	                .clone()
582	                .map(|file| file as Rc<dyn CodeActionProvider>)
583	                .into_iter()
584	                .collect();
585	            lsp.show_document = file.map(|file| show_document(file.document.path.clone(), this));
586	        });
587	
588	        if let Some(document) = &self.document {
589	            self.diagnostics = document.client.diagnostics(&document.path);
590	            let published = document.client.watch_diagnostics();
591	            let path = document.path.clone();
592	            // Collected on a timer rather than awaited: the client reports
593	            // from its own thread, which must not wake app tasks (tests forbid
594	            // it).
595	            self._watch_diagnostics = cx.spawn(async move |this, cx| {
596	                loop {
597	                    cx.background_executor().timer(DIAGNOSTICS_INTERVAL).await;
598	                    let changed: Vec<PathBuf> = published.try_iter().collect();
599	                    if !changed.contains(&path) {
600	                        continue;
601	                    }
602	                    let updated = this.update(cx, |this, cx| {
603	                        if let Some(document) = &this.document {
604	                            this.diagnostics = document.client.diagnostics(&path);
605	                        }
606	                        this.show_diagnostics(cx);
607	                    });
608	                    if updated.is_err() {
609	                        break;
610	                    }
611	                }
612	            });
613	        }
614	        self.show_diagnostics(cx);
615	    }
616	
617	    fn show_diagnostics(&mut self, cx: &mut Context<Self>) {
618	        let diagnostics = &self.diagnostics;
619	        self.editor.update(cx, |editor, cx| {
620	            let text = editor.text().clone();
621	            if let Some(set) = editor.diagnostics_mut() {
622	                set.reset(&text);
623	                set.extend(diagnostics.iter().cloned());
624	            }
625	            cx.notify();
626	        });
627	    }
