629	    /// gpui-kit's completion and code action menus accept on Enter but let
630	    /// the keystroke carry on, which also types a newline: hand the Enter to
631	    /// the menu here and stop it once the menu takes it.
632	    fn route_enter_to_menus(
633	        &mut self,
634	        action: &Enter,
635	        window: &mut Window,
636	        cx: &mut Context<Self>,
637	    ) {
638	        let editor = self.editor.read(cx);
639	        if !editor.completion_menu_state().open && !editor.code_action_menu_state().open {
640	            if !action.shift && self.continues_lists() && self.continue_list(window, cx) {
641	                cx.stop_propagation();
642	            }
643	            return;
644	        }
645	        let action = action.clone();
646	        let accepted = self.editor.update(cx, |editor, cx| {
647	            editor.route_overlay_action(Box::new(action), window, cx)
648	        });
649	        if accepted {
650	            cx.stop_propagation();
651	        }
652	    }
653	}
