656	    /// Whether <Enter> on a list item starts the next: in prose, Markdown or
657	    /// Piton, rather than code, where a line starting with a dash is not one.
658	    fn continues_lists(&self) -> bool {
659	        matches!(self.language.as_str(), "" | "txt" | "md" | "markdown")
