663	    /// <Enter> on a list item, with nothing selected: starts the next item,
664	    /// or ends the list on an empty one. Whether it did either.
665	    fn continue_list(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
666	        let editor = self.editor.read(cx);
667	        // Read-only until the file's text is in.
668	        if !editor.selected_range().is_empty() || self.saved.is_none() {
669	            return false;
670	        }
671	        let text = editor.text();
672	        let cursor = editor.cursor();
673	        let row = text.offset_to_position(cursor).line as usize;
674	        let start = text.line_start_offset(row);
675	        let line = text.slice_line(row).to_string();
676	        let Some(next) = list_continuation(&line, cursor - start) else {
677	            return false;
678	        };
679	        self.editor.update(cx, |editor, cx| match next {
680	            ListEnter::Next(item) => editor.insert(format!("\n{item}"), window, cx),
681	            ListEnter::End(indent) => {
682	                editor.set_selected_range(start..start + line.len(), cx);
683	                editor.replace(indent, window, cx);
684	            }
685	        });
686	        true
687	    }
