711	    /// <Home>, or <Shift+Home> when `select`: to the line's first character
712	    /// that isn't whitespace, or from there to the start of the line.
713	    fn smart_home(&mut self, select: bool, window: &mut Window, cx: &mut Context<Self>) {
714	        let _ = window;
715	        let editor = self.editor.read(cx);
716	        let text = editor.text();
717	        let cursor = editor.cursor();
718	        let row = text.offset_to_position(cursor).line as usize;
719	        let start = text.line_start_offset(row);
720	        let line = text.slice_line(row).to_string();
721	        let target = start + home_column(&line, cursor - start);
722	        let range = editor.selected_range();
723	        // The end of the selection the cursor isn't at stays put.
724	        let anchor = if range.start == cursor {
725	            range.end
726	        } else {
727	            range.start
728	        };
729	        self.editor.update(cx, |editor, cx| {
730	            if select {
731	                editor.set_selected_range(anchor..target, cx);
732	            } else {
733	                editor.set_selected_range(target..target, cx);
734	            }
735	        });
736	        cx.stop_propagation();
737	    }
738	
739	    /// Paints the ruler at [`RULER_COLUMN`], and the darker background past
740	    /// it, from the editor's own layout, so they scroll sideways with the
741	    /// text. Drawn behind the text, whose editor has no background of its own.
742	    fn ruler(&self, cx: &App) -> impl IntoElement {
743	        let editor = self.editor.downgrade();
744	        let color = cx.theme().border;
745	        let (dark, light) = PAST_RULER_SHADE;
746	        let shade = gpui_kit::black().opacity(if cx.theme().is_dark() { dark } else { light });
747	        canvas(
748	            |_, _, _| {},
749	            move |bounds, _, window, cx| {
750	                let Some(editor) = editor.upgrade() else {
751	                    return;
752	                };
753	                let editor = editor.read(cx);
754	                let Some(row) = editor.visible_row_range().map(|rows| rows.start) else {
755	                    return;
756	                };
757	                let text = editor.text();
758	                let row = row.min(text.lines_len().saturating_sub(1));
759	                let start = text.line_start_offset(row);
760	                let Some(line) = editor.range_to_bounds(&(start..start)) else {
761	                    return;
762	                };
763	                let theme = cx.theme();
764	                let text_system = window.text_system();
765	                let font_id = text_system.resolve_font(&font(theme.mono_font_family.clone()));
766	                let column = text_system
767	                    .advance(font_id, theme.mono_font_size, 'm')
768	                    .map_or(theme.mono_font_size * 0.6, |size| size.width);
769	                let x = line.left() + column * RULER_COLUMN as f32;
770	                // Scrolled past, it would lie over the line numbers.
771	                let text_left = line.left() - editor.scroll_offset().x;
772	                if x > bounds.right() {
773	                    return;
774	                }
775	                // The shade runs from the ruler, or from the text's left edge
776	                // once the ruler is scrolled past, to the right edge.
777	                let shade_left = x.max(text_left).round();
778	                window.paint_quad(fill(
779	                    Bounds::from_corners(
780	                        point(shade_left, bounds.top()),
781	                        point(bounds.right(), bounds.bottom()),
782	                    ),
783	                    shade,
784	                ));
785	                if x < text_left {
786	                    return;
787	                }
788	                window.paint_quad(fill(
789	                    Bounds::new(
790	                        point(x.round(), bounds.top()),
791	                        size(px(1.), bounds.size.height),
792	                    ),
793	                    color,
794	                ));
795	            },
796	        )
797	        .absolute()
798	        .inset_0()
799	    }
800	
801	    /// The narrowest the file can be shown: its editor fits 80 columns of
802	    /// text beside its line numbers.
803	    pub fn min_width(&self, window: &Window, cx: &App) -> Pixels {
804	        let theme = cx.theme();
805	        let text_system = window.text_system();
806	        let font_id = text_system.resolve_font(&font(theme.mono_font_family.clone()));
807	        let column = text_system
808	            .advance(font_id, theme.mono_font_size, 'm')
809	            .map_or(theme.mono_font_size * 0.6, |size| size.width);
810	        // Room for the line numbers too, which widen as the file grows.
811	        let lines = self.editor.read(cx).value().lines().count().max(1);
812	        let digits = lines.to_string().len().max(3);
813	        (column * (MIN_COLUMNS + digits + GUTTER_EXTRA_COLUMNS) as f32).ceil()
814	    }
815	}
