970	/// A Piton file open in `piton lsp`; closed there when dropped.
971	struct Document {
972	    client: Arc<LspClient>,
973	    /// Canonical, as the client keys diagnostics.
974	    path: PathBuf,
975	    uri: String,
976	    sent: Mutex<Sent>,
977	    /// Completions from the last request that carry an import.
978	    offered: Mutex<Vec<OfferedCompletion>>,
979	}
980	
981	/// The version and text last sent to the server.
982	struct Sent {
983	    version: i32,
984	    text: String,
985	}
986	
987	struct OfferedCompletion {
988	    /// Byte offset in the file where the completion inserts `new_text`.
989	    start: usize,
990	    new_text: String,
991	    imports: Vec<TextEdit>,
992	}
993	
994	impl Document {
995	    fn open(client: Arc<LspClient>, path: &Path, text: &str) -> Self {
996	        let uri = piton_lsp::file_uri(path);
997	        client
998	            .notify(
999	                "textDocument/didOpen",
1000	                json!({
1001	                    "textDocument": { "uri": uri, "languageId": "piton", "version": 1, "text": text },
1002	                }),
1003	            )
1004	            .ok();
1005	        Self {
1006	            client,
1007	            path: piton_lsp::canonical(path),
1008	            uri,
1009	            sent: Mutex::new(Sent {
1010	                version: 1,
1011	                text: text.to_string(),
1012	            }),
1013	            offered: Mutex::default(),
1014	        }
1015	    }
1016	
1017	    /// Sends `text` to the server, unless it is what the server already has.
1018	    fn sync(&self, text: &str) {
1019	        let mut sent = self.sent.lock().unwrap();
1020	        if sent.text == text {
1021	            return;
1022	        }
1023	        sent.version += 1;
1024	        sent.text = text.to_string();
1025	        self.client
1026	            .notify(
1027	                "textDocument/didChange",
1028	                json!({
1029	                    "textDocument": { "uri": self.uri, "version": sent.version },
1030	                    "contentChanges": [{ "text": text }],
1031	                }),
1032	            )
1033	            .ok();
1034	    }
1035	
1036	    fn did_save(&self) {
1037	        self.client
1038	            .notify(
1039	                "textDocument/didSave",
1040	                json!({ "textDocument": { "uri": self.uri } }),
1041	            )
1042	            .ok();
1043	    }
1044	
1045	    /// `textDocument` and `position` params for byte `offset` of `text`.
1046	    fn at(&self, text: &str, offset: usize) -> Value {
1047	        json!({
1048	            "textDocument": { "uri": self.uri },
1049	            "position": piton_lsp::lsp_position(text, offset),
1050	        })
1051	    }
1052	
1053	    /// The import edits of an offered completion now in `text` where it was
1054	    /// offered, which the editor does not apply itself; last first, so each
1055	    /// applies before the positions of the rest move.
1056	    fn take_accepted_imports(&self, text: &str) -> Vec<TextEdit> {
1057	        let mut offered = self.offered.lock().unwrap();
1058	        let Some(ix) = offered.iter().position(|completion| {
1059	            piton_lsp::is_inserted_at(text, completion.start, &completion.new_text)
1060	        }) else {
1061	            return Vec::new();
1062	        };
1063	        let mut imports = offered.swap_remove(ix).imports;
1064	        offered.clear();
1065	        imports.sort_by(|a, b| b.range.start.cmp(&a.range.start));
1066	        imports
1067	    }
1068	
1069	    /// The edits in `edit` to this file, last first.
1070	    fn edits_in(&self, edit: Option<WorkspaceEdit>) -> Vec<TextEdit> {
1071	        let Some(edit) = edit else {
1072	            return Vec::new();
1073	        };
1074	        let is_this_file = |uri: &lsp_types::Uri| {
1075	            piton_lsp::uri_path(uri.as_str())
1076	                .is_some_and(|path| piton_lsp::canonical(&path) == self.path)
1077	        };
1078	        let mut edits: Vec<TextEdit> = edit
1079	            .changes
1080	            .into_iter()
1081	            .flatten()
1082	            .filter(|(uri, _)| is_this_file(uri))
1083	            .flat_map(|(_, edits)| edits)
1084	            .collect();
1085	        if let Some(DocumentChanges::Edits(changes)) = edit.document_changes {
1086	            edits.extend(
1087	                changes
1088	                    .into_iter()
1089	                    .filter(|change| is_this_file(&change.text_document.uri))
1090	                    .flat_map(|change| change.edits)
1091	                    .map(|edit| match edit {
1092	                        OneOf::Left(edit) => edit,
1093	                        OneOf::Right(annotated) => annotated.text_edit,
1094	                    }),
1095	            );
1096	        }
1097	        edits.sort_by(|a, b| b.range.start.cmp(&a.range.start));
1098	        edits
1099	    }
1100	}
