1118	impl CompletionProvider for PitonFile {
1119	    fn completions(
1120	        &self,
1121	        text: &Rope,
1122	        offset: usize,
1123	        _: CompletionContext,
1124	        _: &mut Window,
1125	        cx: &mut App,
1126	    ) -> Task<Result<CompletionResponse>> {
1127	        let text = text.to_string();
1128	        let document = self.document.clone();
1129	        // The editor asks before it reports the edit that prompted it.
1130	        document.sync(&text);
1131	        cx.background_spawn(async move {
1132	            let result = document
1133	                .client
1134	                .request("textDocument/completion", document.at(&text, offset))?;
1135	            let items =
1136	                piton_lsp::narrow_completions(piton_lsp::completion_items(result)?, &text, offset);
1137	
1138	            *document.offered.lock().unwrap() = items
1139	                .iter()
1140	                .filter_map(|item| {
1141	                    let Some(CompletionTextEdit::Edit(edit)) = &item.text_edit else {
1142	                        return None;
1143	                    };
1144	                    let imports = item
1145	                        .additional_text_edits
1146	                        .clone()
1147	                        .filter(|edits| !edits.is_empty())?;
1148	                    Some(OfferedCompletion {
1149	                        start: piton_lsp::byte_offset(&text, edit.range.start),
1150	                        new_text: edit.new_text.clone(),
1151	                        imports,
1152	                    })
1153	                })
1154	                .collect();
1155	            Ok(CompletionResponse::Array(items))
1156	        })
1157	    }
1158	
1159	    fn is_completion_trigger(&self, _: usize, new_text: &str, _: &mut App) -> bool {
1160	        new_text
1161	            .chars()
1162	            .last()
1163	            .is_some_and(|c| c.is_alphanumeric() || matches!(c, '{' | '.' | '$' | '@' | ':' | '_'))
1164	    }
1165	}
