1199	            let result = document
1200	                .client
1201	                .request("textDocument/definition", document.at(&text, offset))?;
1202	            let link = |location: Location| LocationLink {
1203	                origin_selection_range: None,
1204	                target_uri: location.uri,
1205	                target_range: location.range,
1206	                target_selection_range: location.range,
1207	            };
1208	            Ok(match serde_json::from_value(result)? {
1209	                None => Vec::new(),
1210	                Some(GotoDefinitionResponse::Scalar(location)) => vec![link(location)],
1211	                Some(GotoDefinitionResponse::Array(locations)) => {
1212	                    locations.into_iter().map(link).collect()
1213	                }
1214	                Some(GotoDefinitionResponse::Link(links)) => links,
1215	            })
1216	        })
1217	    }
1218	}
