1373	/// What <Enter> does on a list item.
1374	#[derive(Debug, PartialEq)]
1375	enum ListEnter {
1376	    /// Starts a new line holding the next item's indentation and marker.
1377	    Next(String),
1378	    /// Ends the list: the empty item's line becomes this indentation alone.
1379	    End(String),
1380	}
1381	
1382	/// What <Enter> with the cursor `at` a byte of `line` does, when `line` is a
1383	/// list item, marked with a dash, asterisk, or plus, or a number and a period
1384	/// or parenthesis, then a space; `None` otherwise, or with the cursor before
1385	/// the item's text.
1386	fn list_continuation(line: &str, at: usize) -> Option<ListEnter> {
1387	    let line = line.trim_end_matches(['\n', '\r']);
1388	    let indent_len = line.len() - line.trim_start_matches([' ', '\t']).len();
1389	    let (indent, rest) = line.split_at(indent_len);
1390	    let digits = rest.len() - rest.trim_start_matches(|c: char| c.is_ascii_digit()).len();
1391	    let (marker, next_marker) = if digits > 0 {
1392	        let punct = rest[digits..]
1393	            .chars()
1394	            .next()
1395	            .filter(|c| matches!(c, '.' | ')'))?;
1396	        let number: u64 = rest[..digits].parse().ok()?;
1397	        (&rest[..digits + 1], format!("{}{punct}", number + 1))
1398	    } else {
1399	        let bullet = rest
1400	            .chars()
1401	            .next()
1402	            .filter(|c| matches!(c, '-' | '*' | '+'))?;
1403	        (&rest[..1], bullet.to_string())
1404	    };
1405	    let after = &rest[marker.len()..];
1406	    let space = after.len() - after.trim_start_matches([' ', '\t']).len();
1407	    if space == 0 && !after.is_empty() {
1408	        return None;
1409	    }
1410	    let text_start = indent_len + marker.len() + space;
1411	    if at < text_start.min(line.len()) {
1412	        return None;
1413	    }
1414	    if after.trim().is_empty() {
1415	        return Some(ListEnter::End(indent.to_string()));
1416	    }
1417	    let gap = if space == 0 { " " } else { &after[..space] };
1418	    Some(ListEnter::Next(format!("{indent}{next_marker}{gap}")))
1419	}
