1421	/// `text` in Piton's canonical formatting, from `piton format` run in
1422	/// `project_dir`; an error if it could not be formatted.
1423	pub(crate) fn format_piton(text: &str, project_dir: &Path) -> anyhow::Result<String> {
1424	    use std::io::Write as _;
1425	    use std::process::{Command, Stdio};
1426	
1427	    let mut child = Command::new("piton")
1428	        .args(["format", "-"])
1429	        .current_dir(project_dir)
1430	        .stdin(Stdio::piped())
1431	        .stdout(Stdio::piped())
1432	        .stderr(Stdio::piped())
1433	        .spawn()?;
1434	    // Written from its own thread, so a large file can't fill both pipes.
1435	    let mut stdin = child
1436	        .stdin
1437	        .take()
1438	        .ok_or_else(|| anyhow::anyhow!("no stdin"))?;
1439	    let input = text.to_string();
1440	    let writer = std::thread::spawn(move || stdin.write_all(input.as_bytes()));
1441	    let output = child.wait_with_output()?;
1442	    writer.join().ok();
1443	    if !output.status.success() {
1444	        anyhow::bail!("{}", String::from_utf8_lossy(&output.stderr).trim());
1445	    }
1446	    let formatted = String::from_utf8(output.stdout)?;
1447	    if formatted.trim().is_empty() && !text.trim().is_empty() {
1448	        anyhow::bail!("piton format printed nothing");
1449	    }
1450	    Ok(formatted)
1451	}
