93	impl DiffView {
94	    pub fn new(path: PathBuf, cx: &mut Context<Self>) -> Self {
95	        let title = match ProjectDirectory::get(cx) {
96	            Some(root) => path
97	                .strip_prefix(&root)
98	                .unwrap_or(&path)
99	                .display()
100	                .to_string(),
101	            None => path.display().to_string(),
102	        };
103	        let refresh = cx.spawn({
104	            let path = path.clone();
105	            async move |this, cx| {
106	                loop {
107	                    let content = cx
108	                        .background_spawn({
109	                            let path = path.clone();
110	                            async move { read(&path) }
111	                        })
112	                        .await;
113	                    let updated = this.update(cx, |this, cx| this.show(content, cx));
114	                    if updated.is_err() {
115	                        break;
116	                    }
117	                    cx.background_executor().timer(REFRESH_INTERVAL).await;
118	                }
119	            }
120	        });
121	        Self {
122	            path,
123	            title: title.into(),
124	            layout: layout_preference::load(),
125	            content: Content::Loading,
126	            diff: FileDiff::default(),
127	            expanded: HashSet::new(),
128	            current_change: None,
129	            scroll: UniformListScrollHandle::new(),
130	            focus_handle: cx.focus_handle(),
131	            _refresh: refresh,
132	        }
133	    }
134	
135	    /// The changes to `path`, from the repository's top `top`, between two
136	    /// snapshots of the working tree, the trees `before` and `after`, read
137	    /// from git rather than from disk, so it doesn't follow the file. A
138	    /// renamed file's left side is its old path, `from`, in `before`.
139	    pub fn between(
140	        top: PathBuf,
141	        path: PathBuf,
142	        from: Option<PathBuf>,
143	        before: String,
144	        after: String,
145	        cx: &mut Context<Self>,
146	    ) -> Self {
147	        let mut view = Self::new(top.join(&path), cx);
148	        let load = cx.spawn(async move |this, cx| {
149	            let content = cx
150	                .background_spawn(async move {
151	                    let old =
152	                        task_snapshot::contents(&top, &before, from.as_deref().unwrap_or(&path))
153	                            .unwrap_or_default();
154	                    let new = task_snapshot::contents(&top, &after, &path).unwrap_or_default();
155	                    if new.contains(&0) || old.contains(&0) {
156	                        return Content::Binary;
157	                    }
158	                    Content::Diff {
159	                        old: String::from_utf8_lossy(&old).into_owned(),
160	                        new: String::from_utf8_lossy(&new).into_owned(),
161	                    }
162	                })
163	                .await;
164	            this.update(cx, |this, cx| this.show(content, cx)).ok();
165	        });
166	        // Read once, from the snapshots, in place of following the disk.
167	        view._refresh = load;
168	        view
169	    }
