186	    /// Shows what was read, unless it is what is already shown.
187	    fn show(&mut self, content: Content, cx: &mut Context<Self>) {
188	        if content == self.content {
189	            return;
190	        }
191	        if let Content::Diff { old, new } = &content {
192	            self.diff = FileDiff::compute(old, new);
193	        }
194	        self.content = content;
