207	    fn expand(&mut self, start: usize, cx: &mut Context<Self>) {
208	        self.expanded.insert(start);
209	        self.current_change = None;
210	        cx.notify();
211	    }
212	
213	    /// Whether each row, as laid out now, is a change.
214	    fn row_changes(&self) -> Vec<bool> {
215	        let changed =
216	            |ix: Option<usize>| ix.is_some_and(|ix| self.diff.lines[ix].kind != Kind::Unchanged);
217	        match self.layout {
218	            Layout::Unified => self
219	                .diff
220	                .unified(&self.expanded)
221	                .iter()
222	                .map(|row| matches!(row, UnifiedRow::Line(ix) if changed(Some(*ix))))
223	                .collect(),
224	            Layout::SideBySide => self
225	                .diff
226	                .side_by_side(&self.expanded)
227	                .iter()
228	                .map(|row| matches!(row, SideRow::Pair { old, new } if changed(*old) || changed(*new)))
229	                .collect(),
230	        }
231	    }
