233	    /// The row the change stepped to starts at.
234	    fn current_change_row(&self) -> Option<usize> {
235	        let starts = change_starts(self.row_changes().into_iter());
236	        self.current_change.and_then(|ix| starts.get(ix).copied())
237	    }
