239	    /// Scrolls to the next change, or with `step` of -1 the previous one,
240	    /// stopping at the first and last.
241	    pub fn step_change(&mut self, step: isize, cx: &mut Context<Self>) {
242	        let starts = change_starts(self.row_changes().into_iter());
243	        if starts.is_empty() {
244	            return;
245	        }
246	        let next = match self.current_change {
247	            None if step < 0 => starts.len() - 1,
248	            None => 0,
249	            Some(ix) => (ix as isize + step).clamp(0, starts.len() as isize - 1) as usize,
250	        };
251	        self.current_change = Some(next);
252	        self.scroll
253	            .scroll_to_item(starts[next], ScrollStrategy::Center);
254	        cx.notify();
255	    }
