378	        };
379	        match &self.content {
380	            Content::Loading => return message("Loading…"),
381	            Content::Binary => return message("Binary file; its changes can't be shown."),
382	            Content::Failed(error) => return message(error),
383	            Content::Diff { .. } if self.diff.lines.is_empty() => return message("Empty file"),
384	            Content::Diff { .. } => {}
385	        }
386	
387	        let this = cx.entity().downgrade();
388	        let count = match self.layout {
389	            Layout::Unified => self.diff.unified(&self.expanded).len(),
390	            Layout::SideBySide => self.diff.side_by_side(&self.expanded).len(),
391	        };
392	        let list = uniform_list("diff-rows", count, move |range, _, cx| {
393	            let Some(this) = this.upgrade() else {
394	                return Vec::new();
395	            };
396	            this.update(cx, |this, cx| {
397	                let current = this.current_change_row();
398	                match this.layout {
399	                    Layout::Unified => {
400	                        let rows = this.diff.unified(&this.expanded);
401	                        range
402	                            .map(|ix| {
403	                                this.render_unified_row(ix, &rows[ix], current == Some(ix), cx)
404	                            })
405	                            .collect()
406	                    }
407	                    Layout::SideBySide => {
408	                        let rows = this.diff.side_by_side(&this.expanded);
409	                        range
410	                            .map(|ix| this.render_side_row(ix, &rows[ix], current == Some(ix), cx))
411	                            .collect()
412	                    }
413	                }
414	            })
415	        })
416	        .track_scroll(&self.scroll)
417	        .size_full();
418	        let handle = self.scroll.0.borrow().base_handle.clone();
419	        crate::scrollbar::with_scrollbar("diff", &handle, list, true, None, cx)
420	    }
421	
422	    fn render_unified_row(
423	        &self,
424	        ix: usize,
425	        row: &UnifiedRow,
426	        current: bool,
427	        cx: &mut Context<Self>,
428	    ) -> AnyElement {
429	        match row {
430	            UnifiedRow::Collapsed { start, len } => self.render_collapsed(ix, *start, *len, cx),
431	            UnifiedRow::Line(line_ix) => {
432	                let line = &self.diff.lines[*line_ix];
433	                row_base(("diff-row", ix), line.kind, current, cx)
434	                    .child(number(line.old, cx))
435	                    .child(number(line.new, cx))
436	                    .child(line_text(line, cx))
437	                    .into_any_element()
438	            }
439	        }
440	    }
441	
442	    fn render_side_row(
443	        &self,
444	        ix: usize,
445	        row: &SideRow,
446	        current: bool,
447	        cx: &mut Context<Self>,
448	    ) -> AnyElement {
449	        let (old, new) = match row {
450	            SideRow::Collapsed { start, len } => {
451	                return self.render_collapsed(ix, *start, *len, cx);
452	            }
453	            SideRow::Pair { old, new } => (*old, *new),
454	        };
455	        let half = |line: Option<usize>, old_side: bool, cx: &mut Context<Self>| {
456	            let theme = cx.theme();
457	            match line.map(|ix| &self.diff.lines[ix]) {
458	                Some(line) => {
459	                    let number_on_side = if old_side { line.old } else { line.new };
460	                    row_base(
461	                        ("diff-half", ix * 2 + old_side as usize),
462	                        line.kind,
463	                        false,
464	                        cx,
465	                    )
466	                    .flex_1()
467	                    .min_w_0()
468	                    .child(number(number_on_side, cx))
469	                    .child(line_text(line, cx))
470	                    .into_any_element()
471	                }
472	                // Nothing on this side: blank filler, so the sides stay level.
473	                None => div()
474	                    .flex_1()
475	                    .min_w_0()
476	                    .h(ROW_HEIGHT)
477	                    .bg(theme.muted.opacity(0.5))
478	                    .into_any_element(),
479	            }
480	        };
481	        let left = half(old, true, cx);
482	        let right = half(new, false, cx);
483	        let border = cx.theme().border;
484	        h_flex()
485	            .id(("diff-row", ix))
486	            .w_full()
487	            .h(ROW_HEIGHT)
488	            .when(current, |row| {
489	                row.border_l_2().border_color(cx.theme().ring)
490	            })
491	            .child(left)
492	            .child(div().w_px().h_full().bg(border))
493	            .child(right)
494	            .into_any_element()
495	    }
496	
497	    fn render_collapsed(
498	        &self,
499	        ix: usize,
500	        start: usize,
501	        len: usize,
502	        cx: &mut Context<Self>,
503	    ) -> AnyElement {
504	        let theme = cx.theme();
505	        let label = if len == 1 {
506	            "Show 1 unchanged line".to_string()
507	        } else {
508	            format!("Show {len} unchanged lines")
509	        };
510	        let row = h_flex()
511	            .id(("diff-collapsed", ix))
512	            .w_full()
513	            .h(ROW_HEIGHT)
514	            .gap_2()
515	            .pl(NUMBER_WIDTH)
516	            .text_xs()
517	            .text_color(theme.muted_foreground)
518	            .bg(theme.muted.opacity(0.6))
519	            .cursor_pointer()
520	            .hover(|row| row.text_color(theme.foreground))
521	            .on_click(cx.listener(move |this, _, _, cx| this.expand(start, cx)))
522	            .child(Icon::new(IconName::UnfoldVertical).xsmall())
523	            .child(label);
524	        // Lets UI tests find the row; inert in normal builds.
525	        gpui_kit::TestSupportExt::test_support(row).into_any_element()
526	    }
527	}
528	
529	/// A colour's shade, readable in the light and the dark theme.
530	fn tone(name: ColorName, cx: &App) -> Hsla {
531	    name.scale(if cx.theme().is_dark() { 400 } else { 700 })
532	}
533	
534	/// The tint behind a line of `kind`, and the stronger one behind its changed
535	/// words.
536	fn tints(kind: Kind, cx: &App) -> Option<(Hsla, Hsla)> {
537	    let name = match kind {
538	        Kind::Unchanged => return None,
539	        Kind::Added => ColorName::Green,
540	        Kind::Removed => ColorName::Red,
541	    };
542	    let base = name.scale(500);
543	    let (line, word) = if cx.theme().is_dark() {
544	        (0.14, 0.4)
545	    } else {
546	        (0.1, 0.3)
547	    };
548	    Some((base.opacity(line), base.opacity(word)))
549	}
550	
551	/// A row of a line: tinted by its kind, and marked when it is the change
552	/// stepped to.
553	fn row_base(id: impl Into<ElementId>, kind: Kind, current: bool, cx: &App) -> Stateful<Div> {
554	    let theme = cx.theme();
555	    h_flex()
556	        .id(id)
557	        .w_full()
558	        .h(ROW_HEIGHT)
559	        .font_family(theme.mono_font_family.clone())
560	        .text_size(theme.mono_font_size)
561	        .whitespace_nowrap()
562	        .when_some(tints(kind, cx), |row, (line, _)| row.bg(line))
563	        .when(current, |row| row.border_l_2().border_color(theme.ring))
564	}
565	
566	/// A line number, or blank space where the line has none on this side.
567	fn number(number: Option<usize>, cx: &App) -> Div {
568	    div()
569	        .flex_none()
570	        .w(NUMBER_WIDTH)
571	        .pr_2()
572	        .text_right()
573	        .text_color(cx.theme().muted_foreground)
574	        .children(number.map(|number| number.to_string()))
575	}
576	
577	/// A line's marker (+, −, or nothing) and text, its changed words tinted.
578	fn line_text(line: &Line, cx: &App) -> Div {
579	    let theme = cx.theme();
580	    let (marker, color) = match line.kind {
581	        Kind::Added => ("+", Some(tone(ColorName::Green, cx))),
582	        Kind::Removed => ("−", Some(tone(ColorName::Red, cx))),
583	        Kind::Unchanged => (" ", None),
584	    };
585	    let highlights = tints(line.kind, cx)
586	        .map(|(_, word)| {
587	            line.changed
588	                .iter()
589	                .map(|range| {
590	                    (
591	                        range.clone(),
592	                        HighlightStyle {
593	                            background_color: Some(word),
594	                            ..HighlightStyle::default()
595	                        },
596	                    )
597	                })
598	                .collect::<Vec<_>>()
599	        })
600	        .unwrap_or_default();
601	    h_flex()
602	        .flex_1()
603	        .min_w_0()
604	        .overflow_hidden()
605	        .child(
606	            div()
607	                .flex_none()
608	                .w(px(16.))
609	                .text_center()
610	                .text_color(color.unwrap_or(theme.muted_foreground))
611	                .child(marker),
612	        )
613	        .child(StyledText::new(line.text.clone()).with_highlights(highlights))
614	}
615	
616	impl Render for DiffView {
617	    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
618	        let view = v_flex()
619	            .id("diff-view")
620	            .key_context(CONTEXT)
621	            .track_focus(&self.focus_handle)
622	            .size_full()
623	            .bg(cx.theme().background)
624	            .on_action(cx.listener(|this, _: &NextChange, _, cx| this.step_change(1, cx)))
625	            .on_action(cx.listener(|this, _: &PreviousChange, _, cx| this.step_change(-1, cx)))
626	            .on_mouse_down(
627	                MouseButton::Left,
628	                cx.listener(|this, _, window, cx| this.focus_handle.focus(window, cx)),
629	            )
630	            .child(self.render_header(cx))
631	            .child(div().flex_1().min_h_0().child(self.render_body(cx)));
632	        // Lets UI tests find the view; inert in normal builds.
633	        gpui_kit::TestSupportExt::test_support(view)
634	    }
635	}
636	
637	/// The file as of the last commit, and as it is on disk. A file new since
638	/// then was empty; one no longer on disk is empty now.
639	fn read(path: &Path) -> Content {
640	    let new = match std::fs::read(path) {
641	        Ok(bytes) => bytes,
642	        Err(err) if err.kind() == std::io::ErrorKind::NotFound => Vec::new(),
643	        Err(err) => return Content::Failed(format!("Could not read the file: {err}").into()),
644	    };
645	    let old = committed(path).unwrap_or_default();
646	    if new.contains(&0) || old.contains(&0) {
647	        return Content::Binary;
648	    }
649	    Content::Diff {
650	        old: String::from_utf8_lossy(&old).into_owned(),
651	        new: String::from_utf8_lossy(&new).into_owned(),
652	    }
653	}
654	
655	/// The file's contents as of the last commit, or `None` if it wasn't in it.
656	fn committed(path: &Path) -> Option<Vec<u8>> {
657	    let dir = path.parent()?;
658	    let name = path.file_name()?.to_str()?;
659	    let output = Command::new("git")
660	        .arg("show")
661	        .arg(format!("HEAD:./{name}"))
662	        .current_dir(dir)
663	        .output()
664	        .ok()?;
665	    output.status.success().then_some(output.stdout)
666	}
667	
668	/// Side by side or unified, as last chosen, saved beside the other per-user
669	/// choices. Tests neither read nor write it.
670	mod layout_preference {
671	    use super::Layout;
672	
673	    #[cfg(not(test))]
674	    fn file() -> Option<std::path::PathBuf> {
675	        Some(dirs::config_dir()?.join("suspense").join("diff-layout"))
676	    }
677	
678	    pub fn load() -> Layout {
679	        #[cfg(not(test))]
680	        if let Some(file) = file()
681	            && std::fs::read_to_string(file).is_ok_and(|text| text.trim() == "unified")
682	        {
683	            return Layout::Unified;
684	        }
685	        Layout::SideBySide
686	    }
687	
688	    /// Saves the choice; it is only a convenience, so failing to is ignored.
689	    pub fn save(layout: Layout) {
690	        #[cfg(not(test))]
691	        if let Some(file) = file() {
692	            if let Some(dir) = file.parent() {
693	                std::fs::create_dir_all(dir).ok();
694	            }
695	            let text = match layout {
696	                Layout::SideBySide => "side-by-side",
697	                Layout::Unified => "unified",
698	            };
699	            std::fs::write(file, text).ok();
700	        }
701	        #[cfg(test)]
702	        let _ = layout;
703	    }
704	}
705	
706	#[cfg(test)]
707	mod tests {
708	    use std::path::Path;
709	    use std::time::Duration;
710	
711	    use gpui_kit::component::Root;
712	    use gpui_kit::test::{TestAppContextExt as _, TestWindowExt as _};
713	    use gpui_kit::{AppContext as _, TestAppContext};
714	
715	    use super::{DiffView, Layout};
716	    use crate::piton_syntax;
717	    use crate::project_directory::ProjectDirectory;
718	
719	    const TIMEOUT: Duration = Duration::from_secs(5);
720	
721	    fn git(dir: &Path, args: &[&str]) {
722	        let ok = std::process::Command::new("git")
723	            .args(["-c", "user.name=Test", "-c", "user.email=test@example.com"])
724	            .args(args)
725	            .current_dir(dir)
726	            .output()
727	            .unwrap()
728	            .status
729	            .success();
730	        assert!(ok, "git {args:?} failed");
731	    }
732	
733	    /// A file changed since the last commit shows its changes against the
734	    /// commit, side by side at first; switching to unified lays the same
735	    /// changes out in one column; unchanged lines far from the change
736	    /// collapse, and expand when clicked; F7 steps to the change.
737	    #[gpui_kit::test]
738	    async fn shows_a_files_changes_either_way(cx: &mut TestAppContext) {
739	        let dir = std::env::temp_dir().join(format!("suspense-diff-{}", std::process::id()));
740	        std::fs::remove_dir_all(&dir).ok();
741	        std::fs::create_dir_all(dir.join("src")).unwrap();
742	        let file = dir.join("src/main.rs");
743	        let old: String = (1..=30).map(|n| format!("let line_{n} = {n};\n")).collect();
744	        std::fs::write(&file, &old).unwrap();
745	        git(&dir, &["init", "-q"]);
746	        git(&dir, &["add", "."]);
747	        git(&dir, &["commit", "-q", "-m", "first"]);
748	        std::fs::write(
749	            &file,
750	            old.replace("let line_15 = 15;", "let line_15 = 1500;"),
751	        )
752	        .unwrap();
753	
754	        cx.update(|cx| {
755	            gpui_kit::init(cx);
756	            piton_syntax::init();
757	            ProjectDirectory::init(cx);
758	            ProjectDirectory::set(dir.clone(), cx);
759	            super::bind_keys(cx);
760	        });
761	        let mut view = None;
762	        let window = cx.add_window(|window, cx| {
763	            let diff = cx.new(|cx| DiffView::new(file.clone(), cx));
764	            let focus = diff.read(cx).focus_handle.clone();
765	            focus.focus(window, cx);
766	            view = Some(diff.clone());
767	            Root::new(diff, window, cx)
768	        });
769	        let view = view.unwrap();
770	        let handle = window.into();
771	        cx.wait_for(handle, TIMEOUT, |_, cx| view.read(cx).diff().has_changes())
772	            .await;
773	        view.read_with(cx, |view, _| {
774	            assert_eq!(view.path(), file.as_path());
775	            assert_eq!(view.layout(), Layout::SideBySide);
776	            let diff = view.diff();
777	            assert_eq!((diff.insertions, diff.deletions), (1, 1));
778	            let changed = diff
779	                .lines
780	                .iter()
781	                .find(|line| !line.changed.is_empty())
782	                .unwrap();
783	            assert_eq!(&changed.text[changed.changed[0].clone()], "15;");
784	        });
785	        cx.wait_for(handle, TIMEOUT, |window, _| {
786	            window.try_find(("diff-collapsed", 0usize)).is_some()
787	        })
788	        .await;
789	
790	        cx.update_window(handle, |_, window, cx| window.click("diff-unified", cx))
791	            .unwrap();
792	        cx.run_until_parked();
793	        assert_eq!(view.read_with(cx, |view, _| view.layout()), Layout::Unified);
794	
795	        cx.update_window(handle, |_, window, cx| window.press("f7", cx))
796	            .unwrap();
797	        cx.run_until_parked();
798	        assert_eq!(view.read_with(cx, |view, _| view.current_change), Some(0));
799	
800	        cx.update_window(handle, |_, window, cx| {
801	            window.click(("diff-collapsed", 0usize), cx)
802	        })
803	        .unwrap();
804	        cx.run_until_parked();
805	        view.read_with(cx, |view, _| {
806	            assert!(
807	                view.expanded.contains(&0),
808	                "the unchanged lines did not expand"
809	            );
810	        });
811	        std::fs::remove_dir_all(&dir).ok();
812	    }
813	}
